import sys

def hex_to_rgb(s: str):
    s = s.strip()
    if s.startswith('#'):
        s = s[1:]
    # Problem statement says format #RGB, interpreted as 6 hex digits for R,G,B pairs
    return int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16)

def dist2(a, b):
    return sum((x - y) * (x - y) for x, y in zip(a, b))

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    target = hex_to_rgb(data[0])

    colors = [
        ("black",   (0x00, 0x00, 0x00)),
        ("blue",    (0x00, 0x00, 0xff)),
        ("lime",    (0x00, 0xff, 0x00)),
