        ("red",     (0xff, 0x00, 0x00)),
        ("fuchsia", (0xff, 0x00, 0xff)),
        ("yellow",  (0xff, 0xff, 0x00)),
        ("white",   (0xff, 0xff, 0xff)),
    ]

    best_name = None
    best_d = None

    for name, rgb in colors:
        d = dist2(target, rgb)
        if best_d is None or d < best_d:
            best_d = d
            best_name = name

    print(best_name)

